{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE vahdam_db.maplemonk.vahdam_in_d2c_pnl_line_level AS WITH mapping AS ( SELECT TRIM(\"D2C India\") AS d2c_in_sku, ANY_VALUE(TRIM(\"Common SKU ID\")) AS common_sku_id, ANY_VALUE(TRIM(\"Common SKU Description\")) AS common_sku_description, ANY_VALUE(BRAND) AS brand, ANY_VALUE(CATEGORY) AS category, ANY_VALUE(\"Sub-category\") AS sub_category FROM vahdam_db.maplemonk.vahdam_fy27_inputs_product_mapping WHERE \"D2C India\" IS NOT NULL AND TRIM(\"D2C India\") != \'\' GROUP BY TRIM(\"D2C India\") ), cost_sheet AS ( SELECT TRIM(SKU) AS sku, NULLIF(TRY_TO_DECIMAL(REPLACE(\"COGS (INR)\",\',\',\'\'),30,5), 0) AS cogs_inr, NULLIF(TRY_TO_DECIMAL(REPLACE(\"Duty (INR)\",\',\',\'\'),30,5), 0) AS duty_inr, NULLIF(TRY_TO_DECIMAL(REPLACE(\"Outbound(INR)\",\',\',\'\'),30,5), 0) AS outbound_inr, NULLIF(TRY_TO_DECIMAL(REPLACE(\"Last Mile / mcf\",\',\',\'\'),30,5), 0) AS lastmile_per_unit_inr FROM vahdam_db.maplemonk.fy27_inputs_d2c_india_sc_costs WHERE TRIM(SKU) IS NOT NULL AND TRIM(SKU) != \'\' ), cost_via_common_ranked AS ( SELECT c.sku AS cost_sku, m.common_sku_id, c.cogs_inr, c.duty_inr, c.outbound_inr, c.lastmile_per_unit_inr, ROW_NUMBER() OVER ( PARTITION BY m.common_sku_id ORDER BY CASE WHEN LOWER(c.sku) LIKE \'%frother%\' THEN 1 ELSE 0 END + CASE WHEN LOWER(c.sku) LIKE \'%gift%\' THEN 1 ELSE 0 END + CASE WHEN LOWER(c.sku) LIKE \'%bundle%\' THEN 1 ELSE 0 END + CASE WHEN LOWER(c.sku) LIKE \'%kit%\' THEN 1 ELSE 0 END + CASE WHEN LOWER(c.sku) LIKE \'%pack of%\' THEN 1 ELSE 0 END, LENGTH(c.sku) ) AS rn FROM cost_sheet c JOIN mapping m ON m.d2c_in_sku = c.sku WHERE c.cogs_inr IS NOT NULL ), cost_via_common AS ( SELECT cost_sku, common_sku_id, cogs_inr, duty_inr, outbound_inr, lastmile_per_unit_inr FROM cost_via_common_ranked WHERE rn = 1 ), fy27_cogs AS ( SELECT TRIM(MATERIAL) AS common_sku_id, AVG(TRY_TO_DECIMAL(REPLACE(COGS,\',\',\'\'),30,5)) AS cogs_inr FROM vahdam_db.maplemonk.vahdam_fy27_inputs_cogs_sheet WHERE MATERIAL IS NOT NULL AND TRY_TO_DECIMAL(REPLACE(COGS,\',\',\'\'),30,5) IS NOT NULL GROUP BY TRIM(MATERIAL) ), fx_geo_avg AS ( SELECT CAST(1 AS DECIMAL(30,5)) AS fx_geo_avg_in ), pg_fees AS ( SELECT SOURCE_ORDER_ID AS ORDER_ID, SUM(FEE) AS pg_fee_inr_order FROM VAHDAM_DB.MAPLEMONK.SHOPIFYINDIA_BALANCE_TRANSACTIONS WHERE TYPE = \'charge\' GROUP BY SOURCE_ORDER_ID ), pm_daily_meta AS ( SELECT DATE_START AS day, CAMPAIGN_ID, CAMPAIGN_NAME, SUM(SPEND) AS meta_spend_inr FROM vahdam_db.maplemonk.meta_india_customcampaigns_data WHERE CAMPAIGN_NAME NOT ILIKE \'%AWAR%\' GROUP BY DATE_START, CAMPAIGN_ID, CAMPAIGN_NAME ), pm_daily_google AS ( SELECT \"segments.date\"::DATE AS day, \"campaign.name\" AS campaign_name, SUM(\"metrics.cost_micros\") / 1000000.0 AS google_spend_inr FROM vahdam_db.maplemonk.gads_in_campaign_data GROUP BY \"segments.date\", \"campaign.name\" ), in_campaign_category_map AS ( SELECT CAMPAIGN_ID, ANY_VALUE(CATEGORY) AS mapped_category FROM VAHDAM_DB.MAPLEMONK1.META_INDIA_META_INDIA_CAMPAIGN_MAPPING WHERE CAMPAIGN_ID IS NOT NULL GROUP BY CAMPAIGN_ID ), pm_with_category AS ( SELECT d.day, \'META\' AS source, d.campaign_name, d.meta_spend_inr AS spend_inr, COALESCE(m.mapped_category, \'Supplements\') AS mapped_category FROM pm_daily_meta d LEFT JOIN in_campaign_category_map m ON m.CAMPAIGN_ID = d.CAMPAIGN_ID UNION ALL SELECT day, \'GOOGLE\' AS source, campaign_name, google_spend_inr AS spend_inr, CASE WHEN UPPER(campaign_name) LIKE \'%COFFEE%\' THEN \'Coffee\' WHEN UPPER(campaign_name) LIKE \'%SUPP%\' THEN \'Supplements\' ELSE \'Tea and Botanicals\' END AS mapped_category FROM pm_daily_google ), pm_day_source_cat AS ( SELECT day, source, mapped_category, SUM(spend_inr) AS spend_inr FROM pm_with_category GROUP BY day, source, mapped_category ), predispatch_refunds AS ( SELECT o.ORDER_ID, TO_VARCHAR(o.LINE_ITEM_ID) AS LINE_ITEM_ID, SUM(d.value:Refund_Quantity::FLOAT) AS predispatch_refund_qty FROM vahdam_db.maplemonk.shopifyindia_all_orders_items o, LATERAL FLATTEN(input => o.REFUND_DETAILS) d WHERE o.SHIPPING_CREATED_AT IS NOT NULL AND TRIM(o.SHIPPING_CREATED_AT) <> \'\' AND d.value:Refund_Date::TIMESTAMP < TRY_TO_TIMESTAMP_TZ(o.SHIPPING_CREATED_AT) GROUP BY o.ORDER_ID, TO_VARCHAR(o.LINE_ITEM_ID) ), sales_lines AS ( SELECT DATE(o.ORDER_TIMESTAMP) AS day, o.ORDER_TIMESTAMP, o.ORDER_ID, o.ORDER_NAME, TO_VARCHAR(o.LINE_ITEM_ID) AS LINE_ITEM_ID, LOWER(TRIM(o.EMAIL)) AS customer_email, TO_VARCHAR(o.CUSTOMER) AS customer_id, TRIM(o.SKU) AS line_item_sku, o.PRODUCT_NAME, o.VARIANT_NAME, o.QUANTITY AS qty, o.GROSS_SALES_BEFORE_TAX AS gross_sales_local, o.DISCOUNT_BEFORE_TAX AS discount_local, o.NET_SALES_BEFORE_TAX AS net_sales_local_raw, (COALESCE(o.GROSS_SALES_BEFORE_TAX,0) - COALESCE(o.DISCOUNT_BEFORE_TAX,0)) AS product_revenue_local, o.IS_REFUND, COALESCE(o.REFUND_VALUE, 0) AS refund_value_local, COALESCE(o.REFUND_QUANTITY, 0) AS refund_qty, o.SHIPPING_PRICE AS shipping_price_order_local, o.DISCOUNT AS discount_order_local, o.TOTAL_SALES AS total_sales_order_local, o.TAGS, o.SOURCE AS shopify_source, o.SHOPIFYQL_MAPPED_CHANNEL, o.SHOPIFYQL_MAPPED_SOURCE, o.FINAL_UTM_SOURCE, o.FINAL_UTM_CHANNEL, o.FINAL_UTM_CAMPAIGN, TO_VARCHAR(o.GATEWAY) AS GATEWAY, o.PINCODE, CASE WHEN o.SHIPPING_CREATED_AT IS NULL OR TRIM(o.SHIPPING_CREATED_AT) = \'\' THEN 0 ELSE GREATEST(COALESCE(o.QUANTITY,0) - COALESCE(pr.predispatch_refund_qty,0), 0) END AS shipped_qty FROM vahdam_db.maplemonk.shopifyindia_all_orders_items o LEFT JOIN predispatch_refunds pr ON pr.ORDER_ID = o.ORDER_ID AND pr.LINE_ITEM_ID = TO_VARCHAR(o.LINE_ITEM_ID) WHERE ( (o.ORDER_STATUS != \'CANCELLED\') OR (o.ORDER_STATUS = \'CANCELLED\' AND o.IS_REFUND = 1) ) AND o.SKU IS NOT NULL AND TRIM(o.SKU) != \'\' ), order_meta_lookup AS ( SELECT ORDER_ID, TO_VARCHAR(LINE_ITEM_ID) AS LINE_ITEM_ID, ANY_VALUE(ORDER_NAME) AS ORDER_NAME, ANY_VALUE(LOWER(TRIM(EMAIL))) AS customer_email, ANY_VALUE(TO_VARCHAR(CUSTOMER)) AS customer_id, ANY_VALUE(TRIM(SKU)) AS line_item_sku, ANY_VALUE(PRODUCT_NAME) AS PRODUCT_NAME, ANY_VALUE(VARIANT_NAME) AS VARIANT_NAME, ANY_VALUE(TAGS) AS TAGS, ANY_VALUE(SOURCE) AS shopify_source, ANY_VALUE(SHOPIFYQL_MAPPED_CHANNEL) AS SHOPIFYQL_MAPPED_CHANNEL, ANY_VALUE(SHOPIFYQL_MAPPED_SOURCE) AS SHOPIFYQL_MAPPED_SOURCE, ANY_VALUE(FINAL_UTM_SOURCE) AS FINAL_UTM_SOURCE, ANY_VALUE(FINAL_UTM_CHANNEL) AS FINAL_UTM_CHANNEL, ANY_VALUE(FINAL_UTM_CAMPAIGN) AS FINAL_UTM_CAMPAIGN, ANY_VALUE(TO_VARCHAR(GATEWAY)) AS GATEWAY, ANY_VALUE(PINCODE) AS PINCODE FROM vahdam_db.maplemonk.shopifyindia_all_orders_items GROUP BY ORDER_ID, TO_VARCHAR(LINE_ITEM_ID) ), refund_events_flat AS ( SELECT r.ORDER_ID, r.LINE_ITEM_ID, d.value:Refund_Date::TIMESTAMP AS refund_date, d.value:Refund_Amount::FLOAT AS refund_amount, d.value:Refund_Quantity::FLOAT AS refund_quantity, d.value:Adjustment_Amount::FLOAT AS adjustment_amount FROM VAHDAM_DB.MAPLEMONK.SHOPIFYINDIA_ALL_REFUNDS r, LATERAL FLATTEN(input => r.REFUND_DETAILS) d WHERE d.value:Refund_Date IS NOT NULL ), refund_events AS ( SELECT DATE(rd.refund_date) AS day, rd.refund_date AS ORDER_TIMESTAMP, rd.ORDER_ID, ol.ORDER_NAME, rd.LINE_ITEM_ID, ol.customer_email, ol.customer_id, ol.line_item_sku, ol.PRODUCT_NAME, ol.VARIANT_NAME, -rd.refund_quantity AS qty, CAST(0 AS FLOAT) AS gross_sales_local, CAST(0 AS FLOAT) AS discount_local, -(rd.refund_amount + rd.adjustment_amount) AS net_sales_local_raw, -(rd.refund_amount + rd.adjustment_amount) AS product_revenue_local, 1 AS IS_REFUND, rd.refund_amount AS refund_value_local, rd.refund_quantity AS refund_qty, CAST(0 AS FLOAT) AS shipping_price_order_local, CAST(0 AS FLOAT) AS discount_order_local, CAST(0 AS FLOAT) AS total_sales_order_local, ol.TAGS, ol.shopify_source, ol.SHOPIFYQL_MAPPED_CHANNEL, ol.SHOPIFYQL_MAPPED_SOURCE, ol.FINAL_UTM_SOURCE, ol.FINAL_UTM_CHANNEL, ol.FINAL_UTM_CAMPAIGN, ol.GATEWAY, ol.PINCODE, CAST(0 AS FLOAT) AS shipped_qty FROM refund_events_flat rd LEFT JOIN order_meta_lookup ol ON ol.ORDER_ID = rd.ORDER_ID AND ol.LINE_ITEM_ID = rd.LINE_ITEM_ID ), line_base AS ( SELECT * FROM sales_lines UNION ALL SELECT * FROM refund_events ), customer_history AS ( SELECT customer_email, ORDER_ID, ORDER_TIMESTAMP, DENSE_RANK() OVER ( PARTITION BY customer_email ORDER BY ORDER_TIMESTAMP, ORDER_ID ) AS order_number_for_customer, LAG(ORDER_TIMESTAMP) OVER ( PARTITION BY customer_email ORDER BY ORDER_TIMESTAMP ) AS prev_order_ts, MIN(ORDER_TIMESTAMP) OVER (PARTITION BY customer_email) AS customer_first_order_ts FROM ( SELECT DISTINCT customer_email, ORDER_ID, ORDER_TIMESTAMP FROM sales_lines WHERE customer_email IS NOT NULL AND customer_email != \'\' ) ), customer_cumulative AS ( SELECT customer_email, ORDER_ID, SUM(SUM(product_revenue_local)) OVER ( PARTITION BY customer_email ORDER BY ORDER_TIMESTAMP, ORDER_ID ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS customer_revenue_to_date, SUM(SUM(qty)) OVER ( PARTITION BY customer_email ORDER BY ORDER_TIMESTAMP, ORDER_ID ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS customer_units_to_date FROM sales_lines WHERE customer_email IS NOT NULL AND customer_email != \'\' GROUP BY customer_email, ORDER_ID, ORDER_TIMESTAMP ), customer_acquisition AS ( SELECT customer_email, FINAL_UTM_SOURCE AS acquisition_utm_source, FINAL_UTM_CHANNEL AS acquisition_utm_channel, FINAL_UTM_CAMPAIGN AS acquisition_utm_campaign, SHOPIFYQL_MAPPED_CHANNEL AS acquisition_mapped_channel, SHOPIFYQL_MAPPED_SOURCE AS acquisition_mapped_source FROM ( SELECT customer_email, FINAL_UTM_SOURCE, FINAL_UTM_CHANNEL, FINAL_UTM_CAMPAIGN, SHOPIFYQL_MAPPED_CHANNEL, SHOPIFYQL_MAPPED_SOURCE, ROW_NUMBER() OVER ( PARTITION BY customer_email ORDER BY ORDER_TIMESTAMP, ORDER_ID ) AS rn FROM sales_lines WHERE customer_email IS NOT NULL AND customer_email != \'\' ) WHERE rn = 1 ), order_totals AS ( SELECT ORDER_ID, SUM(qty) AS order_total_qty, SUM(product_revenue_local) AS order_total_product_revenue, SUM(net_sales_local_raw) AS order_total_net_raw, ANY_VALUE(day) AS order_day FROM sales_lines GROUP BY ORDER_ID ), day_category_revenue AS ( SELECT l.day, COALESCE(m.category, \'Tea and Botanicals\') AS category, SUM(l.product_revenue_local) AS cat_product_revenue FROM sales_lines l LEFT JOIN mapping m ON m.d2c_in_sku = l.line_item_sku GROUP BY l.day, COALESCE(m.category, \'Tea and Botanicals\') ), enriched AS ( SELECT l.day, l.ORDER_TIMESTAMP, l.ORDER_ID, l.ORDER_NAME, l.LINE_ITEM_ID, l.line_item_sku, l.PRODUCT_NAME, l.VARIANT_NAME, m.common_sku_id, m.common_sku_description, m.brand, COALESCE(m.category, \'Tea and Botanicals\') AS category, m.sub_category, l.qty, l.shipped_qty, l.gross_sales_local, l.discount_local, l.net_sales_local_raw, l.product_revenue_local, ROUND(COALESCE(l.net_sales_local_raw, 0), 4) AS net_revenue_local, ROUND(COALESCE(l.product_revenue_local, 0), 4) AS product_revenue_net_local, l.refund_value_local, l.refund_qty, l.IS_REFUND, CAST(0 AS DECIMAL(5,2)) AS vat_rate, ROUND(COALESCE(l.product_revenue_local, 0), 4) AS product_revenue_net_ex_vat_local, CASE WHEN l.product_revenue_local <= 0.01 AND l.qty > 0 THEN \'FREE_GIFT\' WHEN l.product_revenue_local > 0 THEN \'PAID\' WHEN l.product_revenue_local < 0 THEN \'REFUND_EVENT\' ELSE \'OTHER\' END AS line_type, cs_direct.cogs_inr AS direct_cogs_inr, cs_direct.duty_inr AS direct_duty_inr, cs_direct.outbound_inr AS direct_outbound_inr, cs_direct.lastmile_per_unit_inr AS direct_lastmile_per_unit_inr, cs_bridge.cogs_inr AS bridge_cogs_inr, cs_bridge.duty_inr AS bridge_duty_inr, cs_bridge.outbound_inr AS bridge_outbound_inr, cs_bridge.lastmile_per_unit_inr AS bridge_lastmile_per_unit_inr, fy27c.cogs_inr AS fy27_cogs_inr, fxg.fx_geo_avg_in AS fx_inr_per_local, l.shipping_price_order_local, l.discount_order_local, l.total_sales_order_local, l.GATEWAY, l.PINCODE, ot.order_total_qty, ot.order_total_product_revenue, ot.order_total_net_raw, CASE WHEN ot.order_total_product_revenue > 0 THEN l.product_revenue_local / ot.order_total_product_revenue ELSE 0 END AS line_share_of_order_revenue, pg.pg_fee_inr_order, l.TAGS, (l.TAGS ILIKE \'%Subscription%\' OR l.TAGS ILIKE \'%Billing cycle%\') AS is_subscription_order, (l.TAGS ILIKE \'%Subscription First Order%\') AS is_subscription_first_order, (l.TAGS ILIKE \'%Subscription Recurring Order%\') AS is_subscription_recurring_order, TRY_TO_NUMBER(REGEXP_SUBSTR(l.TAGS, \'Billing Cycle #([0-9]+)\', 1, 1, \'ie\', 1)) AS billing_cycle_num, TRY_TO_NUMBER(REGEXP_SUBSTR(l.TAGS, \'Pay every ([0-9]+)\', 1, 1, \'ie\', 1)) AS billing_interval_value, UPPER(REGEXP_SUBSTR(l.TAGS, \'Pay every [0-9]+ (DAY|MONTH|WEEK)\', 1, 1, \'ie\', 1)) AS billing_interval_unit, l.customer_email, l.customer_id, ch.order_number_for_customer, (ch.order_number_for_customer = 1) AS is_first_order, (ch.order_number_for_customer > 1) AS is_repeat_order, ch.customer_first_order_ts, DATEDIFF(\'day\', ch.customer_first_order_ts, l.ORDER_TIMESTAMP) AS days_since_first_order, DATEDIFF(\'day\', ch.prev_order_ts, l.ORDER_TIMESTAMP) AS days_since_prev_order, cc.customer_revenue_to_date, cc.customer_units_to_date, ca.acquisition_utm_source, ca.acquisition_utm_channel, ca.acquisition_utm_campaign, ca.acquisition_mapped_channel, ca.acquisition_mapped_source, l.FINAL_UTM_SOURCE AS order_utm_source, l.FINAL_UTM_CHANNEL AS order_utm_channel, l.FINAL_UTM_CAMPAIGN AS order_utm_campaign, l.SHOPIFYQL_MAPPED_CHANNEL AS order_mapped_channel, l.SHOPIFYQL_MAPPED_SOURCE AS order_mapped_source FROM line_base l LEFT JOIN mapping m ON m.d2c_in_sku = l.line_item_sku LEFT JOIN cost_sheet cs_direct ON cs_direct.sku = l.line_item_sku AND cs_direct.cogs_inr IS NOT NULL LEFT JOIN cost_via_common cs_bridge ON cs_bridge.common_sku_id = m.common_sku_id AND m.common_sku_id IS NOT NULL LEFT JOIN fy27_cogs fy27c ON fy27c.common_sku_id = m.common_sku_id AND m.common_sku_id IS NOT NULL CROSS JOIN fx_geo_avg fxg LEFT JOIN order_totals ot ON ot.ORDER_ID = l.ORDER_ID LEFT JOIN pg_fees pg ON pg.ORDER_ID = l.ORDER_ID LEFT JOIN customer_history ch ON ch.ORDER_ID = l.ORDER_ID AND ch.customer_email = l.customer_email LEFT JOIN customer_cumulative cc ON cc.ORDER_ID = l.ORDER_ID AND cc.customer_email = l.customer_email LEFT JOIN customer_acquisition ca ON ca.customer_email = l.customer_email ), category_cost_ratios AS ( SELECT category, CASE WHEN SUM(CASE WHEN COALESCE(direct_cogs_inr, bridge_cogs_inr, fy27_cogs_inr) IS NOT NULL THEN product_revenue_local ELSE 0 END) > 0 THEN SUM(CASE WHEN COALESCE(direct_cogs_inr, bridge_cogs_inr, fy27_cogs_inr) IS NOT NULL THEN qty * COALESCE(direct_cogs_inr, bridge_cogs_inr, fy27_cogs_inr) END) / NULLIF(SUM(CASE WHEN COALESCE(direct_cogs_inr, bridge_cogs_inr, fy27_cogs_inr) IS NOT NULL THEN product_revenue_local ELSE 0 END),0) END AS cogs_pct, CASE WHEN SUM(CASE WHEN COALESCE(direct_duty_inr, bridge_duty_inr) IS NOT NULL THEN product_revenue_local ELSE 0 END) > 0 THEN SUM(CASE WHEN COALESCE(direct_duty_inr, bridge_duty_inr) IS NOT NULL THEN qty * COALESCE(direct_duty_inr, bridge_duty_inr) END) / NULLIF(SUM(CASE WHEN COALESCE(direct_duty_inr, bridge_duty_inr) IS NOT NULL THEN product_revenue_local ELSE 0 END),0) END AS duty_pct, CASE WHEN SUM(CASE WHEN COALESCE(direct_outbound_inr, bridge_outbound_inr) IS NOT NULL THEN product_revenue_local ELSE 0 END) > 0 THEN SUM(CASE WHEN COALESCE(direct_outbound_inr, bridge_outbound_inr) IS NOT NULL THEN qty * COALESCE(direct_outbound_inr, bridge_outbound_inr) END) / NULLIF(SUM(CASE WHEN COALESCE(direct_outbound_inr, bridge_outbound_inr) IS NOT NULL THEN product_revenue_local ELSE 0 END),0) END AS outbound_pct, CASE WHEN SUM(CASE WHEN COALESCE(direct_lastmile_per_unit_inr, bridge_lastmile_per_unit_inr) IS NOT NULL THEN product_revenue_local ELSE 0 END) > 0 THEN SUM(CASE WHEN COALESCE(direct_lastmile_per_unit_inr, bridge_lastmile_per_unit_inr) IS NOT NULL THEN qty * COALESCE(direct_lastmile_per_unit_inr, bridge_lastmile_per_unit_inr) END) / NULLIF(SUM(CASE WHEN COALESCE(direct_lastmile_per_unit_inr, bridge_lastmile_per_unit_inr) IS NOT NULL THEN product_revenue_local ELSE 0 END),0) END AS lastmile_pct FROM enriched WHERE product_revenue_local > 0 GROUP BY category ), enriched_with_fallbacks AS ( SELECT e.*, ccr.cogs_pct AS cat_cogs_pct, ccr.duty_pct AS cat_duty_pct, ccr.outbound_pct AS cat_outbound_pct, ccr.lastmile_pct AS cat_lastmile_pct, CASE WHEN e.direct_cogs_inr IS NOT NULL THEN \'DIRECT\' WHEN e.bridge_cogs_inr IS NOT NULL THEN \'BRIDGE\' WHEN e.fy27_cogs_inr IS NOT NULL THEN \'FY27_COGS\' WHEN ccr.cogs_pct IS NOT NULL THEN \'CAT_REV_PCT\' ELSE \'NO_MATCH\' END AS cogs_match_type, CASE WHEN e.line_type = \'REFUND_EVENT\' OR COALESCE(e.shipped_qty,0) = 0 THEN 0 ELSE COALESCE( e.shipped_qty * e.direct_cogs_inr, e.shipped_qty * e.bridge_cogs_inr, e.shipped_qty * e.fy27_cogs_inr, e.product_revenue_local * ccr.cogs_pct * (e.shipped_qty / NULLIF(e.qty,0)), 0 ) END AS cogs_inr_final, CASE WHEN e.direct_duty_inr IS NOT NULL THEN \'DIRECT\' WHEN e.bridge_duty_inr IS NOT NULL THEN \'BRIDGE\' WHEN ccr.duty_pct IS NOT NULL THEN \'CAT_REV_PCT\' ELSE \'NO_MATCH\' END AS duty_match_type, CASE WHEN e.line_type = \'REFUND_EVENT\' OR COALESCE(e.shipped_qty,0) = 0 THEN 0 ELSE COALESCE( e.shipped_qty * e.direct_duty_inr, e.shipped_qty * e.bridge_duty_inr, e.product_revenue_local * ccr.duty_pct * (e.shipped_qty / NULLIF(e.qty,0)), 0 ) END AS duty_inr_final, CASE WHEN e.direct_outbound_inr IS NOT NULL THEN \'DIRECT\' WHEN e.bridge_outbound_inr IS NOT NULL THEN \'BRIDGE\' WHEN ccr.outbound_pct IS NOT NULL THEN \'CAT_REV_PCT\' ELSE \'NO_MATCH\' END AS outbound_match_type, CASE WHEN e.line_type = \'REFUND_EVENT\' OR COALESCE(e.shipped_qty,0) = 0 THEN 0 ELSE COALESCE( e.shipped_qty * e.direct_outbound_inr, e.shipped_qty * e.bridge_outbound_inr, e.product_revenue_local * ccr.outbound_pct * (e.shipped_qty / NULLIF(e.qty,0)), 0 ) END AS outbound_inr_final, CASE WHEN e.direct_lastmile_per_unit_inr IS NOT NULL THEN \'DIRECT\' WHEN e.bridge_lastmile_per_unit_inr IS NOT NULL THEN \'BRIDGE\' WHEN ccr.lastmile_pct IS NOT NULL THEN \'CAT_REV_PCT\' ELSE \'NO_MATCH\' END AS lastmile_match_type, CASE WHEN e.line_type = \'REFUND_EVENT\' OR COALESCE(e.shipped_qty,0) = 0 THEN 0 ELSE COALESCE( e.shipped_qty * e.direct_lastmile_per_unit_inr, e.shipped_qty * e.bridge_lastmile_per_unit_inr, e.product_revenue_local * ccr.lastmile_pct * (e.shipped_qty / NULLIF(e.qty,0)), 0 ) END AS last_mile_inr_final FROM enriched e LEFT JOIN category_cost_ratios ccr ON ccr.category = e.category ), meta_dim_base AS ( SELECT c.CAMPAIGN_ID, c.CAMPAIGN_NAME, c.ADSET_ID, c.ADSET_NAME, c.AD_ID, c.AD_NAME, COALESCE(m.mapped_category, \'Supplements\') AS mapped_category FROM vahdam_db.maplemonk.meta_india_customcampaigns_data c LEFT JOIN in_campaign_category_map m ON m.CAMPAIGN_ID = c.CAMPAIGN_ID WHERE c.CAMPAIGN_NAME NOT ILIKE \'%AWAR%\' ), meta_dim_by_ad AS ( SELECT AD_ID, ANY_VALUE(CAMPAIGN_ID) AS CAMPAIGN_ID, ANY_VALUE(CAMPAIGN_NAME) AS CAMPAIGN_NAME, ANY_VALUE(ADSET_ID) AS ADSET_ID, ANY_VALUE(ADSET_NAME) AS ADSET_NAME, ANY_VALUE(AD_NAME) AS AD_NAME, ANY_VALUE(mapped_category) AS mapped_category FROM meta_dim_base WHERE AD_ID IS NOT NULL GROUP BY AD_ID ), meta_dim_by_adset AS ( SELECT ADSET_ID, ANY_VALUE(CAMPAIGN_ID) AS CAMPAIGN_ID, ANY_VALUE(CAMPAIGN_NAME) AS CAMPAIGN_NAME, ANY_VALUE(ADSET_NAME) AS ADSET_NAME, ANY_VALUE(mapped_category) AS mapped_category FROM meta_dim_base WHERE ADSET_ID IS NOT NULL GROUP BY ADSET_ID ), meta_dim_by_campaign AS ( SELECT CAMPAIGN_ID, ANY_VALUE(CAMPAIGN_NAME) AS CAMPAIGN_NAME, ANY_VALUE(mapped_category) AS mapped_category FROM meta_dim_base WHERE CAMPAIGN_ID IS NOT NULL GROUP BY CAMPAIGN_ID ), meta_dim_by_name AS ( SELECT UPPER(CAMPAIGN_NAME) AS CAMPAIGN_NAME_UPPER, ANY_VALUE(CAMPAIGN_ID) AS CAMPAIGN_ID, ANY_VALUE(mapped_category) AS mapped_category FROM meta_dim_base WHERE CAMPAIGN_NAME IS NOT NULL GROUP BY UPPER(CAMPAIGN_NAME) ), google_dim_base AS ( SELECT \"campaign.id\"::STRING AS CAMPAIGN_ID, \"campaign.name\" AS CAMPAIGN_NAME, CASE WHEN UPPER(\"campaign.name\") LIKE \'%COFFEE%\' THEN \'Coffee\' WHEN UPPER(\"campaign.name\") LIKE \'%SUPP%\' THEN \'Supplements\' ELSE \'Tea and Botanicals\' END AS mapped_category FROM vahdam_db.maplemonk.gads_in_campaign_data ), google_dim_by_campaign AS ( SELECT CAMPAIGN_ID, ANY_VALUE(CAMPAIGN_NAME) AS CAMPAIGN_NAME, ANY_VALUE(mapped_category) AS mapped_category FROM google_dim_base WHERE CAMPAIGN_ID IS NOT NULL GROUP BY CAMPAIGN_ID ), google_dim_by_name AS ( SELECT UPPER(CAMPAIGN_NAME) AS CAMPAIGN_NAME_UPPER, ANY_VALUE(CAMPAIGN_ID) AS CAMPAIGN_ID, ANY_VALUE(mapped_category) AS mapped_category FROM google_dim_base WHERE CAMPAIGN_NAME IS NOT NULL GROUP BY UPPER(CAMPAIGN_NAME) ), line_with_marketing AS ( SELECT e.*, COALESCE(meta_cat.spend_inr, 0) AS meta_spend_category_day_inr, COALESCE(meta_unm.spend_inr, 0) AS meta_spend_unmapped_day_inr, COALESCE(goog_cat.spend_inr, 0) AS google_spend_category_day_inr, COALESCE(goog_unm.spend_inr, 0) AS google_spend_unmapped_day_inr, COALESCE(dcr.cat_product_revenue, 0) AS day_cat_product_revenue, SUM(COALESCE(dcr.cat_product_revenue,0)) OVER (PARTITION BY e.day) AS day_total_product_revenue, COALESCE(meta_ad.CAMPAIGN_NAME, meta_as.CAMPAIGN_NAME, meta_id.CAMPAIGN_NAME, goog_id.CAMPAIGN_NAME) AS matched_campaign_name, COALESCE(meta_ad.CAMPAIGN_ID, meta_as.CAMPAIGN_ID, meta_id.CAMPAIGN_ID, goog_id.CAMPAIGN_ID) AS matched_campaign_id, COALESCE(meta_ad.ADSET_NAME, meta_as.ADSET_NAME) AS matched_adset_name, COALESCE(meta_ad.ADSET_ID, meta_as.ADSET_ID) AS matched_adset_id, meta_ad.AD_NAME AS matched_ad_name, meta_ad.AD_ID AS matched_ad_id, COALESCE(meta_ad.mapped_category, meta_as.mapped_category, meta_id.mapped_category, goog_id.mapped_category) AS matched_campaign_category, CASE WHEN meta_ad.AD_ID IS NOT NULL THEN \'META_AD_ID_MATCH\' WHEN meta_as.ADSET_ID IS NOT NULL THEN \'META_ADSET_ID_MATCH\' WHEN meta_id.CAMPAIGN_ID IS NOT NULL THEN \'META_CAMPAIGN_ID_MATCH\' WHEN goog_id.CAMPAIGN_ID IS NOT NULL THEN \'GOOGLE_CAMPAIGN_ID_MATCH\' ELSE NULL END AS campaign_match_source, COALESCE(meta_nm.CAMPAIGN_ID, goog_nm.CAMPAIGN_ID) AS matched_by_name_campaign_id, COALESCE(meta_nm.mapped_category, goog_nm.mapped_category) AS matched_by_name_category FROM enriched_with_fallbacks e LEFT JOIN pm_day_source_cat meta_cat ON meta_cat.day = e.day AND meta_cat.source = \'META\' AND meta_cat.mapped_category = e.category LEFT JOIN pm_day_source_cat meta_unm ON meta_unm.day = e.day AND meta_unm.source = \'META\' AND meta_unm.mapped_category = \'UNMAPPED\' LEFT JOIN pm_day_source_cat goog_cat ON goog_cat.day = e.day AND goog_cat.source = \'GOOGLE\' AND goog_cat.mapped_category = e.category LEFT JOIN pm_day_source_cat goog_unm ON goog_unm.day = e.day AND goog_unm.source = \'GOOGLE\' AND goog_unm.mapped_category = \'UNMAPPED\' LEFT JOIN day_category_revenue dcr ON dcr.day = e.day AND dcr.category = e.category LEFT JOIN meta_dim_by_ad meta_ad ON meta_ad.AD_ID = e.order_utm_campaign LEFT JOIN meta_dim_by_adset meta_as ON meta_as.ADSET_ID = e.order_utm_campaign LEFT JOIN meta_dim_by_campaign meta_id ON meta_id.CAMPAIGN_ID = e.order_utm_campaign LEFT JOIN google_dim_by_campaign goog_id ON goog_id.CAMPAIGN_ID = e.order_utm_campaign LEFT JOIN meta_dim_by_name meta_nm ON meta_nm.CAMPAIGN_NAME_UPPER = UPPER(e.order_utm_campaign) LEFT JOIN google_dim_by_name goog_nm ON goog_nm.CAMPAIGN_NAME_UPPER = UPPER(e.order_utm_campaign) ), final_calc AS ( SELECT e.*, CASE WHEN line_type = \'REFUND_EVENT\' THEN 0 ELSE COALESCE(net_sales_local_raw, 0) * 0.015 END AS pg_fee_local, \'FIXED_1.5PCT\' AS pg_match_type_v, CASE WHEN line_type = \'REFUND_EVENT\' THEN 0 WHEN is_subscription_order THEN COALESCE(net_revenue_local, 0) * 0.007 ELSE 0 END AS loop_commission_local, CASE WHEN line_type = \'REFUND_EVENT\' THEN 0 ELSE COALESCE( meta_spend_category_day_inr * CASE WHEN day_cat_product_revenue > 0 THEN product_revenue_local / day_cat_product_revenue ELSE 0 END + meta_spend_unmapped_day_inr * CASE WHEN day_total_product_revenue > 0 THEN product_revenue_local / day_total_product_revenue ELSE 0 END , 0) END AS meta_spend_local, CASE WHEN line_type = \'REFUND_EVENT\' THEN 0 ELSE COALESCE( google_spend_category_day_inr * CASE WHEN day_cat_product_revenue > 0 THEN product_revenue_local / day_cat_product_revenue ELSE 0 END + google_spend_unmapped_day_inr * CASE WHEN day_total_product_revenue > 0 THEN product_revenue_local / day_total_product_revenue ELSE 0 END , 0) END AS google_spend_local FROM line_with_marketing e ), mis_raw AS ( SELECT TRIM(\"MIS Head\") AS mis, DATE_FROM_PARTS(2000 + TRY_TO_NUMBER(SPLIT_PART(mth,\'-\',2)), DECODE(UPPER(SPLIT_PART(mth,\'-\',1)),\'JAN\',1,\'FEB\',2,\'MAR\',3,\'APR\',4,\'MAY\',5,\'JUN\',6, \'JUL\',7,\'AUG\',8,\'SEP\',9,\'OCT\',10,\'NOV\',11,\'DEC\',12), 1) AS month_start, TRY_TO_DECIMAL(REPLACE(NULLIF(TRIM(val),\'\'),\',\',\'\'),30,4) AS amt_inr FROM vahdam_db.maplemonk1.tool_costs_sheet_to_fill__aug_26_onwards_ UNPIVOT INCLUDE NULLS (val FOR mth IN (\"Apr-26\",\"May-26\",\"Jun-26\",\"Jul-26\",\"Aug-26\",\"Sep-26\", \"Oct-26\",\"Nov-26\",\"Dec-26\",\"Jan-27\",\"Feb-27\",\"Mar-27\")) WHERE UPPER(TRIM(\"Channel Group\")) = \'D2C\' AND UPPER(TRIM(\"GEO\")) = \'IND\' ), mis_month AS ( SELECT mis, month_start, SUM(amt_inr) AS amt_inr FROM mis_raw GROUP BY 1,2 ), mis_filled AS ( SELECT mis, month_start, COALESCE(amt_inr, AVG(amt_inr) OVER (PARTITION BY mis ORDER BY month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) AS amt_used_inr, IFF(amt_inr IS NULL, 1, 0) AS is_imputed FROM mis_month ), mis_wide AS ( SELECT month_start, SUM(IFF(mis = \'Agency Cost\', amt_used_inr, 0)) AS agency_inr, SUM(IFF(mis ILIKE \'Software and Platform Fee%\', amt_used_inr, 0)) AS software_inr, MAX(IFF(mis = \'Agency Cost\', is_imputed, 0)) AS agency_imputed, MAX(IFF(mis ILIKE \'Software and Platform Fee%\', is_imputed, 0)) AS software_imputed FROM mis_filled GROUP BY 1 ), final_calc2 AS ( SELECT c.*, c.meta_spend_local + c.google_spend_local AS pm_spend_total_local, CASE WHEN c.day >= DATE \'2026-04-01\' AND COALESCE(c.day_total_product_revenue,0) > 0 THEN COALESCE(mw.agency_inr,0) / DAY(LAST_DAY(c.day)) / 1.0 * (c.product_revenue_local / c.day_total_product_revenue) ELSE 0 END AS agency_cost_local, CASE WHEN c.day >= DATE \'2026-04-01\' AND COALESCE(c.day_total_product_revenue,0) > 0 THEN COALESCE(mw.software_inr,0) / DAY(LAST_DAY(c.day)) / 1.0 * (c.product_revenue_local / c.day_total_product_revenue) ELSE 0 END AS software_platform_fee_local, IFF(c.day >= DATE \'2026-04-01\', COALESCE(mw.agency_imputed,0), 0) AS agency_cost_imputed, IFF(c.day >= DATE \'2026-04-01\', COALESCE(mw.software_imputed,0), 0) AS software_platform_fee_imputed, COALESCE(c.net_revenue_local, 0) - COALESCE(c.cogs_inr_final, 0) - COALESCE(c.duty_inr_final, 0) - COALESCE(c.last_mile_inr_final, 0) - c.pg_fee_local - c.loop_commission_local AS cm1_local FROM final_calc c LEFT JOIN mis_wide mw ON mw.month_start = DATE_TRUNC(\'MONTH\', c.day) ) SELECT \'IN\' AS geography, c.day, c.ORDER_TIMESTAMP, c.ORDER_ID, c.ORDER_NAME, c.TAGS, c.LINE_ITEM_ID, c.line_item_sku, c.common_sku_id, c.common_sku_description, c.brand, c.category, c.sub_category, c.PRODUCT_NAME, c.VARIANT_NAME, c.line_type, c.qty, c.vat_rate, ROUND(c.gross_sales_local, 4) AS gross_sales_inr, ROUND(c.gross_sales_local / 90.53, 4) AS gross_sales_usd, ROUND(c.gross_sales_local / 121.05, 4) AS gross_sales_gbp, ROUND(c.discount_local, 4) AS discount_inr, ROUND(c.discount_local / 90.53, 4) AS discount_usd, ROUND(c.discount_local / 121.05, 4) AS discount_gbp, ROUND(c.net_sales_local_raw, 4) AS net_sales_raw_inr, ROUND(c.net_sales_local_raw / 90.53, 4) AS net_sales_raw_usd, ROUND(c.net_sales_local_raw / 121.05, 4) AS net_sales_raw_gbp, ROUND(c.product_revenue_local, 4) AS product_revenue_inr, ROUND(c.product_revenue_local / 90.53, 4) AS product_revenue_usd, ROUND(c.product_revenue_local / 121.05, 4) AS product_revenue_gbp, ROUND(c.product_revenue_net_local, 4) AS product_revenue_net_of_refunds_inr, ROUND(c.product_revenue_net_local / 90.53, 4) AS product_revenue_net_of_refunds_usd, ROUND(c.product_revenue_net_local / 121.05, 4) AS product_revenue_net_of_refunds_gbp, ROUND(c.product_revenue_net_ex_vat_local, 4) AS product_revenue_net_ex_vat_inr, ROUND(c.product_revenue_net_ex_vat_local / 90.53, 4) AS product_revenue_net_ex_vat_usd, ROUND(c.product_revenue_net_ex_vat_local / 121.05, 4) AS product_revenue_net_ex_vat_gbp, ROUND(c.net_revenue_local, 4) AS net_revenue_inr, ROUND(c.net_revenue_local / 90.53, 4) AS net_revenue_usd, ROUND(c.net_revenue_local / 121.05, 4) AS net_revenue_gbp, ROUND(c.cogs_inr_final, 4) AS cogs_inr, ROUND(c.cogs_inr_final / 90.53, 4) AS cogs_usd, ROUND(c.cogs_inr_final / 121.05, 4) AS cogs_gbp, ROUND(c.duty_inr_final, 4) AS duty_inr, ROUND(c.duty_inr_final / 90.53, 4) AS duty_usd, ROUND(c.duty_inr_final / 121.05, 4) AS duty_gbp, CAST(0 AS NUMBER(18,4)) AS outbound_inr, CAST(0 AS NUMBER(18,4)) AS outbound_usd, CAST(0 AS NUMBER(18,4)) AS outbound_gbp, ROUND(c.last_mile_inr_final, 4) AS last_mile_inr, ROUND(c.last_mile_inr_final / 90.53, 4) AS last_mile_usd, ROUND(c.last_mile_inr_final / 121.05, 4) AS last_mile_gbp, CAST(0 AS NUMBER(18,4)) AS three_pl_inr, CAST(0 AS NUMBER(18,4)) AS three_pl_usd, CAST(0 AS NUMBER(18,4)) AS three_pl_gbp, CAST(0 AS NUMBER(18,4)) AS storage_inr, CAST(0 AS NUMBER(18,4)) AS storage_usd, CAST(0 AS NUMBER(18,4)) AS storage_gbp, ROUND(c.pg_fee_local, 4) AS pg_fee_inr, ROUND(c.pg_fee_local / 90.53, 4) AS pg_fee_usd, ROUND(c.pg_fee_local / 121.05, 4) AS pg_fee_gbp, ROUND(c.loop_commission_local, 4) AS loop_commission_inr, ROUND(c.loop_commission_local / 90.53, 4) AS loop_commission_usd, ROUND(c.loop_commission_local / 121.05, 4) AS loop_commission_gbp, ROUND(c.meta_spend_local, 4) AS meta_spend_inr, ROUND(c.meta_spend_local / 90.53, 4) AS meta_spend_usd, ROUND(c.meta_spend_local / 121.05, 4) AS meta_spend_gbp, ROUND(c.google_spend_local, 4) AS google_spend_inr, ROUND(c.google_spend_local / 90.53, 4) AS google_spend_usd, ROUND(c.google_spend_local / 121.05, 4) AS google_spend_gbp, ROUND(c.pm_spend_total_local, 4) AS pm_spend_total_inr, ROUND(c.pm_spend_total_local / 90.53, 4) AS pm_spend_total_usd, ROUND(c.pm_spend_total_local / 121.05, 4) AS pm_spend_total_gbp, ROUND(c.agency_cost_local * 1, 4) AS agency_cost_inr, ROUND(c.agency_cost_local, 4) AS agency_cost_local_ccy, ROUND(c.software_platform_fee_local * 1, 4) AS software_platform_fee_inr, ROUND(c.software_platform_fee_local, 4) AS software_platform_fee_local_ccy, c.agency_cost_imputed, c.software_platform_fee_imputed, ROUND((c.pm_spend_total_local + c.agency_cost_local + c.software_platform_fee_local) * 1, 4) AS cm1_to_cm2_costs_inr, ROUND(c.pm_spend_total_local + c.agency_cost_local + c.software_platform_fee_local, 4) AS cm1_to_cm2_costs_local_ccy, CASE WHEN c.day_cat_product_revenue > 0 THEN c.product_revenue_local / c.day_cat_product_revenue ELSE 0 END AS line_share_of_day_category_revenue, CASE WHEN c.day_total_product_revenue > 0 THEN c.product_revenue_local / c.day_total_product_revenue ELSE 0 END AS line_share_of_day_total_revenue, ROUND(c.cm1_local, 4) AS cm1_inr, ROUND(c.cm1_local / 90.53, 4) AS cm1_usd, ROUND(c.cm1_local / 121.05, 4) AS cm1_gbp, ROUND(c.cm1_local - c.pm_spend_total_local - c.agency_cost_local - c.software_platform_fee_local, 4) AS cm2_inr, ROUND((c.cm1_local - c.pm_spend_total_local - c.agency_cost_local - c.software_platform_fee_local) / 90.53, 4) AS cm2_usd, ROUND((c.cm1_local - c.pm_spend_total_local - c.agency_cost_local - c.software_platform_fee_local) / 121.05, 4) AS cm2_gbp, c.refund_qty, c.IS_REFUND AS is_refund, ROUND(c.refund_value_local, 4) AS refund_value_inr, ROUND(c.refund_value_local / 90.53, 4) AS refund_value_usd, ROUND(c.refund_value_local / 121.05, 4) AS refund_value_gbp, ROUND(c.shipping_price_order_local, 4) AS shipping_price_order_inr, ROUND(c.shipping_price_order_local / 90.53, 4) AS shipping_price_order_usd, ROUND(c.shipping_price_order_local / 121.05, 4) AS shipping_price_order_gbp, ROUND(c.discount_order_local, 4) AS discount_order_inr, ROUND(c.discount_order_local / 90.53, 4) AS discount_order_usd, ROUND(c.discount_order_local / 121.05, 4) AS discount_order_gbp, ROUND(c.total_sales_order_local, 4) AS total_sales_order_inr, ROUND(c.total_sales_order_local / 90.53, 4) AS total_sales_order_usd, ROUND(c.total_sales_order_local / 121.05, 4) AS total_sales_order_gbp, c.order_total_qty, ROUND(c.order_total_product_revenue, 4) AS order_total_product_revenue_inr, ROUND(c.order_total_product_revenue / 90.53, 4) AS order_total_product_revenue_usd, ROUND(c.order_total_product_revenue / 121.05, 4) AS order_total_product_revenue_gbp, c.line_share_of_order_revenue, c.GATEWAY AS payment_gateway, c.PINCODE AS shipping_postcode, c.customer_email, c.customer_id, c.order_number_for_customer, c.is_first_order, c.is_repeat_order, c.customer_first_order_ts, c.days_since_first_order, c.days_since_prev_order, ROUND(c.customer_revenue_to_date, 4) AS customer_revenue_to_date_inr, ROUND(c.customer_revenue_to_date / 90.53, 4) AS customer_revenue_to_date_usd, ROUND(c.customer_revenue_to_date / 121.05, 4) AS customer_revenue_to_date_gbp, c.customer_units_to_date, c.is_subscription_order, c.is_subscription_first_order, c.is_subscription_recurring_order, c.billing_cycle_num, c.billing_interval_value, c.billing_interval_unit, CASE c.billing_interval_unit WHEN \'DAY\' THEN c.billing_interval_value WHEN \'WEEK\' THEN c.billing_interval_value * 7 WHEN \'MONTH\' THEN c.billing_interval_value * 30 ELSE NULL END AS billing_interval_days, (CASE c.billing_interval_unit WHEN \'DAY\' THEN c.billing_interval_value WHEN \'WEEK\' THEN c.billing_interval_value * 7 WHEN \'MONTH\' THEN c.billing_interval_value * 30 ELSE NULL END = 30) AS is_30_day_plan, c.acquisition_utm_source, c.acquisition_utm_channel, c.acquisition_utm_campaign, c.acquisition_mapped_channel, c.acquisition_mapped_source, c.order_utm_source, c.order_utm_channel, c.order_utm_campaign, c.order_mapped_channel, c.order_mapped_source, CASE WHEN c.is_subscription_recurring_order OR c.billing_cycle_num > 1 THEN \'SUBSCRIPTION_RENEWAL\' WHEN UPPER(c.order_utm_source) IN (\'META\',\'FACEBOOK\',\'FB\',\'INSTAGRAM\',\'IG\') THEN \'META\' WHEN UPPER(c.order_utm_source) IN (\'GOOGLE\',\'BING\',\'YAHOO\') THEN \'SEARCH\' WHEN UPPER(c.order_utm_source) IN (\'TIKTOK\') THEN \'TIKTOK\' WHEN UPPER(c.order_utm_source) IN (\'KLAVIYO\') THEN \'EMAIL\' WHEN UPPER(c.order_utm_source) IN (\'SHOP_APP\') THEN \'SHOP_APP\' WHEN c.order_utm_source ILIKE \'%vahdam%\' OR c.order_utm_source ILIKE \'%try.vahdam%\' THEN \'OWNED_LP\' WHEN UPPER(c.order_utm_source) = \'DIRECT\' THEN \'DIRECT\' WHEN c.order_utm_source IS NULL OR TRIM(c.order_utm_source) = \'\' THEN \'UNKNOWN\' ELSE \'OTHER\' END AS acquisition_channel_normalised, COALESCE( c.matched_campaign_category, c.matched_by_name_category, CASE WHEN UPPER(c.order_utm_campaign) LIKE \'%COFFEE%\' THEN \'Coffee\' WHEN UPPER(c.order_utm_campaign) LIKE \'%SUPP%\' THEN \'Supplements\' ELSE NULL END ) AS acquisition_product_category, c.matched_campaign_id, c.matched_campaign_name, c.matched_adset_id, c.matched_adset_name, c.matched_ad_id, c.matched_ad_name, c.matched_campaign_category, c.matched_by_name_campaign_id, c.cogs_match_type, c.duty_match_type, c.outbound_match_type, c.lastmile_match_type, c.pg_match_type_v AS pg_match_type, c.campaign_match_source, c.cat_cogs_pct, c.cat_duty_pct, c.cat_outbound_pct, c.cat_lastmile_pct, c.fx_inr_per_local AS fx_inr_per_gbp FROM final_calc2 c ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from VAHDAM_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
